dashboard.definition:
{
  "title": "5 · Environmental Device Health",
  "description": "Correlate room temperature with device errors to prevent heat-related failures.",
  "inputs": {},
  "defaults": {},
  "visualizations": {
    "bg_001": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "bg_002": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#16A3B0",
        "strokeColor": "#16A3B0",
        "strokeWidth": 1,
        "rx": 3
      }
    },
    "md_003": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "USE CASE 5 OF 9  ·  SPITAL AARWALD  ·  SAMPLE DATA",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "md_004": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# Environmental Device Health",
        "fontColor": "#E6EDF3"
      }
    },
    "md_005": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "A label printer failed from heat. Splunk joins room climate with device errors and warns early.",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 15
      }
    },
    "bg_006": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#11161D",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 8
      }
    },
    "md_007": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "WHAT WE HEARD",
        "fontColor": "#6E7681",
        "fontSize": "custom",
        "customFontSize": 11
      }
    },
    "md_008": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "*“Etikettendrucker, der dieses Jahr aufgrund steigender Temperaturen nicht mehr funktioniert hat.”*",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_009": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_010": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "labs · pharmacy · IT rooms · storage",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13
      },
      "dataSources": {
        "primary": "ds_011"
      },
      "title": "Rooms monitored"
    },
    "bg_012": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_013": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "> majorValue | rangeValue(majorColorConfig)",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "off",
        "underLabel": "C1-104 · B1-012",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_014"
      },
      "title": "Rooms above limit now",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ],
        "majorColorConfig": [
          {
            "to": 1,
            "value": "#0CA30C"
          },
          {
            "from": 1,
            "value": "#D03B3B"
          }
        ]
      }
    },
    "bg_015": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_016": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "> majorValue | rangeValue(majorColorConfig)",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "rolling 7-day count",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_017"
      },
      "title": "Label printer errors (7 days)",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ],
        "majorColorConfig": [
          {
            "to": 20,
            "value": "#E6EDF3"
          },
          {
            "from": 20,
            "value": "#FAB219"
          }
        ]
      }
    },
    "bg_018": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_019": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "> majorValue | rangeValue(majorColorConfig)",
        "numberPrecision": 1,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "unit": "°C",
        "unitPosition": "after",
        "underLabel": "Lab storage C1-104 (printer room)",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_020"
      },
      "title": "Hottest room now",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ],
        "majorColorConfig": [
          {
            "to": 28,
            "value": "#0CA30C"
          },
          {
            "from": 28,
            "to": 30,
            "value": "#FAB219"
          },
          {
            "from": 30,
            "value": "#D03B3B"
          }
        ]
      }
    },
    "bg_021": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_022": {
      "type": "splunk.line",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "nullValueDisplay": "connect",
        "lineWidth": 2,
        "seriesColors": [
          "#D95926",
          "#3987E5",
          "#199E70",
          "#6E7681"
        ],
        "yAxisTitleVisibility": "hide",
        "lineDashStylesByField": {
          "Printer max. rating": "dash"
        }
      },
      "dataSources": {
        "primary": "ds_023"
      },
      "title": "Room temperature (°C) — last 7 days"
    },
    "bg_024": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_025": {
      "type": "splunk.markergauge",
      "options": {
        "backgroundColor": "#161B22",
        "orientation": "horizontal",
        "majorTickInterval": 5,
        "gaugeRanges": [
          {
            "from": 15,
            "to": 26,
            "value": "#0CA30C"
          },
          {
            "from": 26,
            "to": 30,
            "value": "#FAB219"
          },
          {
            "from": 30,
            "to": 40,
            "value": "#D03B3B"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_026"
      },
      "title": "Lab storage C1-104 — now (°C)"
    },
    "bg_027": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_028": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#161B22",
        "headerVisibility": "fixed",
        "fontSize": "small",
        "columnFormat": {
          "Device": {
            "width": 105
          },
          "Type": {
            "width": 140
          },
          "Room": {
            "width": 170
          },
          "Temp now": {
            "width": 90
          },
          "Rated max": {
            "width": 90
          },
          "Errors today": {
            "width": 100
          },
          "Status": {
            "width": 95,
            "rowBackgroundColors": "> table | seriesByName(\"Status\") | matchValue(c0Bg)",
            "rowColors": "> table | seriesByName(\"Status\") | matchValue(c0Fg)"
          }
        }
      },
      "dataSources": {
        "primary": "ds_029"
      },
      "title": "Devices vs. their rated operating range",
      "context": {
        "c0Bg": [
          {
            "match": "Over limit",
            "value": "#3F1D20"
          },
          {
            "match": "Near limit",
            "value": "#3A2E12"
          },
          {
            "match": "OK",
            "value": "#12301B"
          }
        ],
        "c0Fg": [
          {
            "match": "Over limit",
            "value": "#FF8A80"
          },
          {
            "match": "Near limit",
            "value": "#E3B341"
          },
          {
            "match": "OK",
            "value": "#56D364"
          }
        ]
      }
    },
    "bg_030": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_031": {
      "type": "splunk.column",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "seriesColors": [
          "#D95926",
          "#3987E5",
          "#9085E9"
        ],
        "stackMode": "stacked",
        "yAxisTitleVisibility": "hide"
      },
      "dataSources": {
        "primary": "ds_032"
      },
      "title": "Label printer errors per day"
    },
    "bg_033": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "md_034": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "DATA SOURCES NEEDED IN SPLUNK",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "bg_035": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_036": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "SNMP (interfaces & devices)",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_037": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_038": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "IoT platform / gateway",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_039": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_040": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Building management (BMS)",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_041": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_042": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "CMDB / asset inventory",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    }
  },
  "dataSources": {
    "ds_011": {
      "type": "ds.search",
      "name": "ds_011",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n29,64\n28,64\n27,65\n26,66\n25,67\n24,67\n23,68\n22,69\n21,70\n20,70\n19,71\n18,72\n17,73\n16,73\n15,74\n14,75\n13,76\n12,76\n11,77\n10,78\n9,79\n8,79\n7,80\n6,81\n5,82\n4,82\n3,83\n2,84\n1,85\n0,85\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_014": {
      "type": "ds.search",
      "name": "ds_014",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n1,1\n0,2\"\n| eval _time=relative_time(now(), \"@h\") - ago*3600\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_017": {
      "type": "ds.search",
      "name": "ds_017",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n13,6\n12,5\n11,7\n10,6\n9,8\n8,9\n7,12\n6,15\n5,21\n4,27\n3,33\n2,38\n1,44\n0,47\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_020": {
      "type": "ds.search",
      "name": "ds_020",
      "options": {
        "query": "| makeresults format=csv data=\"ago,t\n23,28.96\n22,29.14\n21,29.29\n20,29.49\n19,29.51\n18,29.72\n17,29.39\n16,29.73\n15,30.1\n14,30.07\n13,30.32\n12,30.05\n11,30.35\n10,30.36\n9,30.63\n8,30.76\n7,30.6\n6,30.83\n5,30.98\n4,31.42\n3,31.47\n2,31.29\n1,31.73\n0,31.8\"\n| eval _time=relative_time(now(), \"@h\") - ago*3600\n| sort 0 _time\n| table _time t",
